import{z as E,x as l,o as n,c as B,q as o,j as p,D as r,d as t,s,S as c,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"ftrace 与 tracepoints","description":"","frontmatter":{"title":"ftrace 与 tracepoints","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ftrace-tracepoints.md","filePath":"cs/ftrace-tracepoints.md","lastUpdated":1791063341000}'),d={name:"cs/ftrace-tracepoints.md"};function f(A,a,u,m,h,T){const i=l("Mermaid");return n(),B("div",null,[a[2]||(a[2]=o('<h1 id="ftrace-与-tracepoints" tabindex="-1">ftrace 与 tracepoints <a class="header-anchor" href="#ftrace-与-tracepoints" aria-label="Permalink to &quot;ftrace 与 tracepoints&quot;">​</a></h1><div class="epigraph"><p>tracepoint 是编译进内核的钩，默认几乎为零成本；ftrace 把它们接到环形缓冲，并可做函数图与过滤。</p><footer>—— 据 Rostedt 对 ftrace 的论述；Linux tracepoint 文档；[printk](/cs/printk-logging) 为重日志对照</footer></div><p><a href="/cs/printk-logging">printk</a> 太重。<a href="/cs/napi">NAPI</a> 路径不能每包打印。缺口是 <strong>ftrace</strong>：tracepoint、function tracer、ring。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>TRACE_EVENT</code> 定义字段。启用才把探针插入。缺口：buffer per-cpu；过滤 pid/comm；function tracer 用 mcount。本课不把每个事件名列出。</p><p><span class="marginnote">tracefs 是接口。对象是事件流，不是 gdb。与 eBPF 后课可共用 tracepoint。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>echo 1 &gt; events/.../enable</code> → 事件写 per-cpu 缓冲 → <code>trace_pipe</code> 读。对照 <a href="/cs/perf-sampling">perf</a> 后课：perf 可消费同一点。对照 <a href="/cs/inotify">inotify</a>：一个文件树，一个内核执行点。对照 ASan：一个找空间错，一个找时间线。</p><p><span class="marginnote">per-CPU 缓冲就是「每个核各记各的账本」：事件在哪个核上发生，就写进那个核私有的环形缓冲，读的时候再按核拼接时间线，避免了多核抢同一块内存的锁。</span></p>',9)),(n(),p(c,null,{default:r(()=>[s(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TP%5B%22tracepoint%22%5D%20--%3E%20FILT%5B%22%E8%BF%87%E6%BB%A4%E5%99%A8%22%5D%0A%20%20FILT%20--%3E%20BUF%5B%22per-CPU%20%E7%8E%AF%22%5D%0A%20%20BUF%20--%3E%20USER%5B%22trace_pipe%20%2F%20perf%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[t("ftrace 把「生产内核可观测」收成零开销默认 + 按需启用，是调试延迟与调度的主工具。不要写成 APM 产品。与 "),e("a",{href:"/cs/preempt-rt"},"PREEMPT_RT"),t("：tracer 本身扰动，要测开/关。")],-1)),a[5]||(a[5]=e("p",null,"错误过滤仍可让缓冲溢出丢事件。",-1)),a[6]||(a[6]=e("p",null,"tracepoint 为什么默认零开销？关键在「编译进去但默认关闭」：探针位置在二进制里只是一条空指令，启用时才被改写成真正的调用。",-1)),(n(),p(c,null,{default:r(()=>[s(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOP%5B%22%E6%9C%AA%E5%90%AF%E7%94%A8%EF%BC%9A%E6%8E%A2%E9%92%88%E5%A4%84%E6%98%AF%E4%B8%80%E6%9D%A1%20nop%20%E7%A9%BA%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20ECHO%5B%22echo%201%20%3E%20enable%22%5D%0A%20%20ECHO%20--%3E%20PATCH%5B%22%E6%8E%A2%E9%92%88%E4%BD%8D%E6%94%B9%E5%86%99%E4%B8%BA%E8%B0%83%E7%94%A8%22%5D%0A%20%20PATCH%20--%3E%20FIRE%5B%22%E4%BA%8B%E4%BB%B6%E8%B7%AF%E5%BE%84%E6%89%A7%E8%A1%8C%E5%88%B0%E8%BF%99%E9%87%8C%22%5D%0A%20%20FIRE%20--%3E%20WRITE%5B%22%E5%86%99%E6%9C%AC%E6%A0%B8%20per-CPU%20%E7%BC%93%E5%86%B2%22%5D%0A%20%20WRITE%20--%3E%20FULL%7B%22%E7%BC%93%E5%86%B2%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20FULL%20--%20%22%E5%90%A6%22%20--%3E%20KEEP%5B%22%E8%AE%B0%E5%BD%95%E4%BF%9D%E7%95%99%EF%BC%8C%E7%AD%89%E7%94%A8%E6%88%B7%E8%AF%BB%22%5D%0A%20%20FULL%20--%20%22%E6%98%AF%22%20--%3E%20DROP%5B%22%E4%B8%A2%E5%BC%83%E6%96%B0%E4%BA%8B%E4%BB%B6%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：把 buffer_size_kb 设成 4096（即每个核 4 MB），在一台 32 核机器上，环形缓冲总共占 32 × 4 MB = 128 MB 内核内存——跟踪是有账单的，核越多越贵。</span></p><p><span class="marginnote">常见误区：初学者容易把 tracepoint 想成 gdb 那种会让程序停下来的断点。实际上它只往缓冲里记一条数据就立刻继续跑，内核几乎感觉不到；真正会拖慢系统的是 function tracer 这类高频探针。</span></p><p>实现上：per-cpu 缓冲避免全局锁，读的时候可能看到撕裂，工具用页头同步。function tracer 用 mcount/patchable 入口，和 livepatch 抢同一套改代码机制。 读法上只引用<a href="/cs/printk-logging">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>ftrace 与 tracepoints</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 tracer 插件。不保证模块事件的稳定性。下一课动态打点：kprobes。</p><p>版本字段会变，课序钉的是机制对象「ftrace 与 tracepoints」，不是某一主线内核的结构体名。 后课默认：静态 tracepoint 可低成本启用。动态探针 kprobe/uprobe，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tracepoint 默认便宜；ftrace 收集到 per-CPU 环。</li><li>函数跟踪更重，适合短时。</li><li>kprobes 是下一课。</li><li>出处：ftrace 文档；Rostedt；tracepoint。</li></ul>',10))])}const P=E(d,[["render",f]]);export{C as __pageData,P as default};
